-- Online Education: law_college SQL Dump
-- Total records: 5,470 BCI Approved Law Colleges & Courses

CREATE TABLE IF NOT EXISTS `law_college` (
  `id` int NOT NULL AUTO_INCREMENT,
  `state` varchar(100) DEFAULT NULL,
  `affiliating_university` varchar(500) DEFAULT NULL,
  `name` varchar(500) DEFAULT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `course_name` varchar(255) DEFAULT NULL,
  `approval_till` varchar(150) DEFAULT NULL,
  `e_year` varchar(50) DEFAULT NULL,
  `remarks` text,
  `status` varchar(50) NOT NULL DEFAULT 'ACTIVE',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int NOT NULL DEFAULT '0',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_law_college_slug` (`slug`),
  KEY `idx_law_college_state` (`state`),
  KEY `idx_law_college_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

